  GogdlApiImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  GogdlApiImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_GogdlApi,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_GogdlApi,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_GogdlApiPtr,
  );

  Future<String> getBackgroundImageLink({required int gameId}) => RustLib
      .instance
      .api
      .crateApiGogdlGogdlApiGetBackgroundImageLink(that: this, gameId: gameId);

  Future<String> getGameBoxartLink({required int gameId}) => RustLib
      .instance
      .api
      .crateApiGogdlGogdlApiGetGameBoxartLink(that: this, gameId: gameId);

  Future<String> getGameTitle({required int gameId}) => RustLib.instance.api
      .crateApiGogdlGogdlApiGetGameTitle(that: this, gameId: gameId);

  String getLoginLink() =>
      RustLib.instance.api.crateApiGogdlGogdlApiGetLoginLink(that: this);

  Future<Int32List> getOwnedGames() =>
      RustLib.instance.api.crateApiGogdlGogdlApiGetOwnedGames(that: this);

  Future<void> restoreAuth({required String jsonStr}) => RustLib.instance.api
      .crateApiGogdlGogdlApiRestoreAuth(that: this, jsonStr: jsonStr);
}
